import * as THREE from './assets/three.module.js';
const host=document.getElementById('crown-scene');
try{const renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));host.append(renderer.domElement);const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(35,1,.1,100);camera.position.set(0,1.9,6.6);camera.lookAt(0,.2,0);scene.add(new THREE.HemisphereLight(0xffe4cf,0x452039,3));const light=new THREE.DirectionalLight(0xffd6a0,5);light.position.set(3,5,4);scene.add(light);const pink=new THREE.PointLight(0xff7fbb,25);pink.position.set(-3,1,2);scene.add(pink);const crown=new THREE.Group();scene.add(crown);const gold=new THREE.MeshStandardMaterial({color:0xe6b66b,metalness:.78,roughness:.24});const gem=new THREE.MeshPhysicalMaterial({color:0xef9caf,metalness:.3,roughness:.1,clearcoat:1});
function ring(y,r,t){const m=new THREE.Mesh(new THREE.TorusGeometry(r,t,12,80),gold);m.rotation.x=Math.PI/2;m.position.y=y;crown.add(m)}ring(0,1,.075);ring(.22,1.02,.045);ring(-.15,.98,.035);const band=new THREE.Mesh(new THREE.CylinderGeometry(1.02,.98,.28,64,1,true),gold);band.position.y=.02;crown.add(band);
for(let i=0;i<8;i++){const a=i*Math.PI/4;const points=[new THREE.Vector3(Math.cos(a-.36),.2,Math.sin(a-.36)),new THREE.Vector3(Math.cos(a)*1.1,.9+(i%2===0?.18:0),Math.sin(a)*1.1),new THREE.Vector3(Math.cos(a+.36),.2,Math.sin(a+.36))];const curve=new THREE.CatmullRomCurve3(points);crown.add(new THREE.Mesh(new THREE.TubeGeometry(curve,24,.045,8,false),gold));const jewel=new THREE.Mesh(new THREE.OctahedronGeometry(.12,0),gem);jewel.position.copy(points[1]);crown.add(jewel);const orb=new THREE.Mesh(new THREE.SphereGeometry(.06,12,12),gold);orb.position.copy(points[1]);orb.position.y+=.16;crown.add(orb);const diamond=new THREE.Mesh(new THREE.OctahedronGeometry(.085),gem);diamond.position.set(Math.cos(a)*1.03,.04,Math.sin(a)*1.03);crown.add(diamond)}
const stars=new THREE.Group();scene.add(stars);for(let i=0;i<24;i++){const star=new THREE.Mesh(new THREE.OctahedronGeometry(.018+Math.random()*.025),new THREE.MeshBasicMaterial({color:0xf4d6aa}));const a=Math.random()*Math.PI*2;star.position.set(Math.cos(a)*(1.5+Math.random()),(Math.random()-.5)*2,Math.sin(a)*1.5);stars.add(star)}let target=0;host.onpointermove=e=>{const r=host.getBoundingClientRect();target=(e.clientX-r.left)/r.width*2-1};host.onpointerleave=()=>target=0;const resize=()=>{renderer.setSize(host.clientWidth,host.clientHeight);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix()};resize();addEventListener('resize',resize);let last=0;function frame(t){requestAnimationFrame(frame);if(document.hidden)return;if(!window.motionPaused){const delta=Math.min((t-last)/1000,.05);crown.rotation.y+=delta*.23;crown.rotation.z=Math.sin(t*.0006)*.07;crown.rotation.x+=(target*.15-crown.rotation.x)*.04;crown.position.y=Math.sin(t*.001)*.06;stars.rotation.y=t*.00008}last=t;renderer.render(scene,camera)}requestAnimationFrame(frame)}catch{host.innerHTML='<span style="display:block;text-align:center;font-size:90px;color:#e5bf89;padding-top:50px" aria-label="Golden crown">♛</span>'}
